function IdeaCard({ idea, onOpen }: { idea: typeof ideas[number]; onOpen: () => void }) {
  return <article className="app-card border-t-[3px] p-5" style={{ borderTopColor: idea.tone === "teal" ? "#12a383" : idea.tone === "violet" ? "#7c5ce0" : "#2f80ed" }}>
    <div className="flex flex-wrap items-center justify-between gap-2"><span className={`pill ${idea.tone === "teal" ? "text-[#0e9f7a] border-[#0e9f7a]/45" : idea.tone === "violet" ? "text-[#6d4bd8] border-[#6d4bd8]/45" : "text-blue border-blue/45"}`}>{idea.category}</span><StatusPill tone={idea.band === "Priority" ? "sand" : idea.band === "Qualify" ? "teal" : "muted"}>{idea.band}</StatusPill></div>
    <button onClick={onOpen} className="mt-3 text-left text-base font-medium leading-snug hover:text-blue">{idea.kind === "problem" ? "🔎 " : ""}{idea.title}</button>
    <p className="mt-2 text-sm text-muted">{idea.summary}</p>
    <div className="mt-3 flex items-center gap-2"><Avatar name={idea.author} /><span className="flex-1 text-sm"><b className="font-medium">{idea.author}</b> <span className="text-muted">{idea.department}</span></span><span className="font-mono text-xs tracking-[.08em] text-muted">{idea.ref}</span></div>
    <div className="mt-3 flex flex-wrap gap-2"><button className="btn btn-small"><Icon name="up" className="h-4 w-4" /> {idea.supports} Support</button><button onClick={onOpen} className="btn btn-small"><Icon name="msg" className="h-4 w-4" /> {idea.comments} Discuss</button></div>
  </article>;
}

