function LegacyNewIdeaPage() {
  const [kind, setKind] = useState("idea");
  const [step, setStep] = useState(1);
  const [raw, setRaw] = useState("");
  const [title, setTitle] = useState("");
  const [summary, setSummary] = useState("");
  const fields = [{ label: "Problem statement", placeholder: "What problem are you solving?" }, { label: "Proposed solution", placeholder: "What would you change?" }, { label: "Expected benefits", placeholder: "Who benefits and how?" }, { label: "Possible risks", placeholder: "What should reviewers think about?" }];
  return <div className="stack"><Hero art="submit" title="Share an idea" subtitle="Turn a customer or colleague insight into a clear proposal the bank can act on." /><div className="grid grid-cols-5 gap-1.5 overflow-hidden sm:gap-2">{["Describe", "Develop", "Questions", "Pass or fail", "Numbers"].map((label, index) => <div key={label} className={`flex items-center gap-2 rounded-[11px] border px-2.5 py-2.5 text-[13px] font-medium ${step === index + 1 ? "border-blue bg-blue/[.12] text-ink" : step > index + 1 ? "text-muted" : "text-[var(--dim)]"}`} style={{ borderColor: step === index + 1 ? "var(--blue)" : "var(--line)" }}><b className={`grid h-[22px] w-[22px] shrink-0 place-items-center rounded-full border text-xs ${step > index + 1 ? "border-[#0e9f7a] text-[#0e9f7a]" : step === index + 1 ? "border-blue bg-blue text-white" : ""}`} style={{ borderColor: step > index + 1 || step === index + 1 ? undefined : "var(--line-strong)" }}>{step > index + 1 ? "✓" : index + 1}</b><span className="hidden sm:inline">{label}</span></div>)}</div>
    {step === 1 && <div className="app-card"><Tabs items={["💡 An idea", "🔎 A problem"]} active={kind === "idea" ? "💡 An idea" : "🔎 A problem"} onChange={(value) => setKind(value.startsWith("💡") ? "idea" : "problem")} /><label className="mt-5 block"><span className="field-label">{kind === "idea" ? "Your idea in your own words" : "What is slowing customers or colleagues down?"}</span><textarea className="input min-h-[124px] resize-y" value={raw} onChange={(event) => setRaw(event.target.value)} placeholder="Describe it in your own words…" /></label><div className="mt-4 flex gap-2 rounded-xl border border-dashed px-3.5 py-3 text-[13px] text-muted" style={{ borderColor: "var(--line-strong)" }}><Icon name="bot" className="mt-0.5 h-5 w-5 shrink-0 text-blue" /><span><b className="font-medium text-sand">The AI coach is connected.</b> It will check originality, structure your proposal and suggest questions reviewers may ask.</span></div><button className="btn-primary mt-4" onClick={() => setStep(2)}><Icon name="spark" /> Check originality and continue</button></div>}
    {step === 2 && <><div className="flex gap-2 rounded-xl border border-solid px-3.5 py-3 text-[13px] text-muted" style={{ borderColor: "rgba(14,159,122,.35)", background: "rgba(14,159,122,.07)" }}><Icon name="check" className="mt-0.5 h-5 w-5 shrink-0 text-[#0e9f7a]" /><span><b className="font-medium text-[#0e9f7a]">Originality check passed.</b> No registered idea matches yours.</span></div><div className="app-card"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-xl font-medium">Develop your idea</h2><p className="mt-1 text-muted">Fill in the sections. The more specific you are, the better the validation.</p></div><StatusPill tone="blue">Customer</StatusPill></div><div className="mt-4 grid gap-4 sm:grid-cols-2"><label className="block sm:col-span-2"><span className="field-label">Idea title</span><input className="input" value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Give your idea a clear title" /></label><label className="block sm:col-span-2"><span className="field-label">In one or two sentences</span><textarea className="input min-h-[90px]" value={summary} onChange={(event) => setSummary(event.target.value)} placeholder="Summarise the change and its value" /></label>{fields.map((field) => <label key={field.label} className="block"><span className="field-label">{field.label}</span><textarea className="input min-h-[124px]" placeholder={field.placeholder} /></label>)}</div></div><div className="flex flex-wrap gap-2"><button className="btn" onClick={() => setStep(1)}>Back</button><button className="btn-primary" onClick={() => setStep(3)}><Icon name="bot" /> Answer five questions</button></div></>}
    {step === 3 && <div className="app-card"><div className="flex items-start gap-3"><div className="icon-box"><Icon name="bot" /></div><div><h2 className="text-xl font-medium">Questions reviewers may ask</h2><p className="mt-1 text-muted">Use these prompts to find the weak spots before you submit.</p></div></div><div className="mt-4 space-y-3"><label className="block rounded-xl border-l-2 px-3 py-1" style={{ borderColor: "var(--line-strong)" }}><span className="font-medium">Who experiences this problem today?</span><textarea className="input mt-2 min-h-[76px]" placeholder="Your answer" /></label><label className="block rounded-xl border-l-2 px-3 py-1" style={{ borderColor: "var(--line-strong)" }}><span className="font-medium">What evidence tells you it is worth solving?</span><textarea className="input mt-2 min-h-[76px]" placeholder="Your answer" /></label><label className="block rounded-xl border-l-2 px-3 py-1" style={{ borderColor: "var(--line-strong)" }}><span className="font-medium">What could make the proposal difficult?</span><textarea className="input mt-2 min-h-[76px]" placeholder="Your answer" /></label></div><div className="mt-4 flex gap-2"><button className="btn" onClick={() => setStep(2)}>Back</button><button className="btn-primary" onClick={() => setStep(4)}>Validate my idea</button></div></div>}
    {step === 4 && <div className="app-card"><div className="flex items-start gap-3"><div className="icon-box" style={{ color: "var(--sand)", background: "rgba(217,119,6,.12)" }}><Icon name="shield" /></div><div><h2 className="text-xl font-medium">Validation passed</h2><p className="mt-1 text-muted">Your proposal has enough detail for a reviewer to assess it.</p></div></div><div className="mt-5 grid gap-3 sm:grid-cols-3">{[["Customer impact", "2.4", "Qualify"], ["Business value", "2.1", "Qualify"], ["Feasibility", "2.8", "Priority"]].map(([label, score, band]) => <div key={label} className="tile text-center"><span className="block text-sm text-muted">{label}</span><b className="my-1 block text-3xl font-semibold">{score}</b><StatusPill tone={band === "Priority" ? "sand" : "teal"}>{band}</StatusPill></div>)}</div><div className="mt-5 flex flex-wrap gap-2"><button className="btn" onClick={() => setStep(3)}>Back</button><button className="btn-primary" onClick={() => setStep(5)}>Continue to numbers</button></div></div>}
    {step === 5 && <div className="app-card"><h2 className="text-xl font-medium">Add impact numbers</h2><p className="mt-1 text-muted">Rough estimates are enough. Reviewers will refine them later.</p><div className="mt-4 grid gap-4 sm:grid-cols-3">{[["Turnaround time", "% faster"], ["Volume", "per month"], ["Expected savings or revenue", "JOD per year"]].map(([label, unit]) => <label key={label} className="block"><span className="field-label">{label}</span><input className="input" placeholder="0" /><span className="mt-1 block text-xs text-muted">{unit}</span></label>)}</div><div className="mt-5 flex flex-wrap gap-2"><button className="btn" onClick={() => setStep(4)}>Back</button><button className="btn-primary" onClick={() => setStep(6)}>Submit idea</button></div></div>}
    {step === 6 && <div className="app-card py-14 text-center"><div className="icon-box mx-auto mb-3" style={{ color: "var(--teal)", background: "rgba(14,159,122,.12)" }}><Icon name="check" /></div><h1 className="text-2xl font-medium">Submitted</h1><p className="mx-auto mt-2 max-w-[52ch] text-muted">Your idea is registered as <b>ABI-2026-00015</b>. An innovation reviewer screens it first, and you are notified at every step.</p><button className="btn-primary mt-5" onClick={() => setStep(1)}>Share another idea</button></div>}
  </div>;
}

