const articles = [["Letters of credit: how the documentary principle protects both sides", "Why banks pay against documents rather than goods, and what makes a presentation compliant.", "Banking Excellence", "7 min", "AB"], ["Root-cause analysis: 5 Whys and fishbone, done properly", "How to get beneath symptoms to causes you can actually fix.", "Innovation & Business Transformation", "6 min", "AB"], ["Understanding responsible AI in banking", "Fairness, transparency, data minimisation and human oversight, in practical banking terms.", "Technology & AI", "6 min", "AB"], ["Making change stick: adoption, not announcement", "Why people keep the old spreadsheet, and what actually changes behaviour.", "Innovation & Business Transformation", "5 min", "HBR"]];

