function LiveLibraryPage({ onArticle }: { onArticle: (id: number) => void }) {
  const [tab, setTab] = useState("All");
  const categoryMap: Record<string, string | undefined> = { All: undefined, Recommended: undefined, Banking: "banking", Transformation: "transformation", Technology: "technology" };
  const category = categoryMap[tab];
  const articlesQuery = useArticles(category);
  const recommendations = useLearningRecommendations();
  const isRecommended = tab === "Recommended";
  const query = isRecommended ? recommendations : articlesQuery;
  const items = isRecommended ? recommendations.data?.items ?? [] : articlesQuery.data?.items ?? [];
  return <div className="stack"><Hero art="library" title="Library" subtitle="Practical reading for better ideas, sharper decisions and stronger outcomes." /><Tabs items={["All", "Recommended", "Banking", "Transformation", "Technology"]} active={tab} onChange={setTab} />{query.isPending ? <LearningState state="loading" label="Loading the library…" /> : query.isError ? <LearningState state="error" label="The library could not be loaded." onRetry={() => void query.refetch()} /> : <ArticleList articles={items} onOpen={(article) => onArticle(article.id)} />}</div>;
}

function LiveArticlePage({ articleId, onBack }: { articleId: number | null; onBack: () => void }) {
  const articleQuery = useLearningArticle(articleId ?? 0, Boolean(articleId));
  const complete = useCompleteArticle();
  if (articleQuery.isPending) return <LearningState state="loading" label="Loading article…" />;
  if (articleQuery.isError || !articleQuery.data) return <div className="stack"><LearningState state="error" label="This article could not be loaded." onRetry={() => void articleQuery.refetch()} /><button className="btn self-start" type="button" onClick={onBack}>Back to Library</button></div>;
  const article = articleQuery.data;
  return <div className="stack"><button className="btn btn-small self-start" type="button" onClick={onBack}><Icon name="back" className="h-4 w-4" /> Back to Library</button><ArticleCard article={article} onComplete={() => complete.mutate({ articleId: article.id })} pending={complete.isPending} completed={false} successMessage={complete.isSuccess ? `${complete.data.alreadyCompleted ? "Already completed" : "Completed"} — ${complete.data.pointsAwarded} points awarded.${complete.data.badgeAwards?.length ? ` Badge unlocked (${complete.data.badgeAwards.length}).` : ""}` : undefined} errorMessage={complete.isError ? (complete.error instanceof Error ? complete.error.message : "The article could not be completed.") : undefined} /></div>;
}

function LiveRewardsPage() {
  const rewards = useRewards();
  const redemptions = useRedemptions();
  const request = useRequestRedemption();
  if (rewards.isPending) return <div className="stack"><Hero art="rewards" title="Rewards" subtitle="Your ideas, learning and collaboration add up to Ignite Points and recognition." /><RewardsState state="loading" /></div>;
  if (rewards.isError || !rewards.data) return <div className="stack"><Hero art="rewards" title="Rewards" subtitle="Your ideas, learning and collaboration add up to Ignite Points and recognition." /><RewardsState state="error" label="Rewards could not be loaded." onRetry={() => void rewards.refetch()} /></div>;
  const { balance, level, redeemable, earned, badges } = rewards.data;
  return <div className="stack"><Hero art="rewards" title="Rewards" subtitle="Your ideas, learning and collaboration add up to Ignite Points and recognition." /><RewardsBalanceCard balance={balance} level={level} /><section className="stack"><SectionHeading title="Rewards you can redeem" detail={`${redeemable.length} available rewards`} /><RewardCatalogue rewards={redeemable} balance={balance.balance} pendingRewardId={request.isPending ? Number(request.variables?.rewardId) : undefined} onRedeem={(reward) => request.mutate({ rewardId: reward.id })} />{request.isError && <p className="rounded-xl border border-pink/30 bg-pink/10 p-3 text-sm text-[#d6336c]" role="alert">{request.error instanceof Error ? request.error.message : "The redemption could not be created."}</p>}</section><section className="stack"><SectionHeading title="Earned recognition" detail="Milestones you have unlocked" /><RewardCatalogue rewards={earned} balance={balance.balance} /></section><section className="stack"><SectionHeading title="Badges" detail="Recognition for the moments that move ideas forward" /><BadgeProgressList badges={badges} /></section><section className="stack"><SectionHeading title="Redemption history" detail="Your requests and fulfilment status" />{redemptions.isPending ? <RewardsState state="loading" /> : redemptions.isError ? <RewardsState state="error" label="Redemption history could not be loaded." onRetry={() => void redemptions.refetch()} /> : <RedemptionHistory redemptions={redemptions.data.items} />}</section></div>;
}

function LegacyIdeaDetailPage({ onBack }: { onBack: () => void }) {
  return <div className="stack"><button className="btn btn-small self-start" onClick={onBack}><Icon name="back" className="h-4 w-4" /> Back to Community</button><section className="app-card"><div className="flex flex-wrap items-center justify-between gap-2"><StatusPill tone="blue">Customer</StatusPill><StatusPill>Screening</StatusPill></div><h1 className="mt-4 text-[28px] font-medium leading-tight">Mobile Camera Bill Scanning Feature for Arabi App</h1><div className="mt-3 flex items-center gap-2"><Avatar name="Raghad Aljadid" /><span className="text-sm"><b className="font-medium">Raghad Aljadid</b> <span className="text-muted">Technology</span></span></div><div className="my-5 grid grid-cols-7 gap-1.5">{["Submitted", "Business review", "Control review", "Confirmation", "Proof of concept", "Implementation", "Impact"].map((stage, index) => <div key={stage} className={`text-center text-[11px] ${index === 0 ? "text-sand" : "text-[var(--dim)]"}`}><span className={`mx-auto mb-1 grid h-8 w-8 place-items-center rounded-full border ${index === 0 ? "border-sand text-sand" : ""}`} style={{ borderColor: index === 0 ? "var(--sand)" : "var(--line-strong)" }}><Icon name={index === 0 ? "bulb" : "check"} className="h-4 w-4" /></span><span className="hidden sm:block">{stage}</span></div>)}</div><div className="flex gap-2 rounded-xl border p-3 text-sm" style={{ borderColor: "var(--line-strong)" }}><Icon name="lock" className="mt-0.5 h-5 w-5 shrink-0 text-blue" /><div><b className="font-medium">Registered to Raghad Aljadid, Technology</b><p className="text-muted">Record ABI-2026-00013, registered 15 Oct 2026. Supporters and commenters are credited by name.</p></div></div><p className="mt-5 text-base">I suggest to add feature on arabi mobile to scan the bills using mobile camera instead of adding the bills manually</p><div className="mt-4 grid gap-2 sm:grid-cols-2"><div className="tile"><small className="block text-xs text-muted">Problem</small><span>Customers enter bill details manually, which takes time and creates errors.</span></div><div className="tile"><small className="block text-xs text-muted">Solution</small><span>Use the phone camera to scan and validate the bill details.</span></div><div className="tile"><small className="block text-xs text-muted">Expected benefits</small><span>Faster payments and fewer data-entry mistakes.</span></div><div className="tile"><small className="block text-xs text-muted">Risks</small><span>Needs good image quality and safe validation rules.</span></div></div><button className="btn-primary mt-4"><Icon name="up" /> 0 Support this idea</button></section><section className="app-card"><h2 className="text-xl font-medium">Discussion <span className="font-normal text-muted">(0)</span></h2><p className="mt-2 text-sm text-muted">No comments yet. Be the first.</p><div className="mt-4 flex items-end gap-2"><textarea className="input min-h-[76px]" placeholder="Add a comment or a suggestion" /><button className="btn-primary">Post</button></div></section></div>;
}

function isProtectedViewProps(value: unknown): value is { protectedView?: boolean } {
  return typeof value === "object" && value !== null && "protectedView" in value && (value as { protectedView?: unknown }).protectedView === true;
}

export default function Home(props: unknown) {
  const protectedView = isProtectedViewProps(props);
  const [signedIn, setSignedIn] = useState(protectedView);
  const [page, setPage] = useState<Page>("community");
  const [selectedIdeaId, setSelectedIdeaId] = useState<number | null>(null);
  const [selectedArticleId, setSelectedArticleId] = useState<number | null>(null);
  const [menuOpen, setMenuOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const notificationsQuery = useEmployeeNotifications(signedIn);
  const rewardsSummaryQuery = useRewards(signedIn);
  const setNotificationRead = useSetEmployeeNotificationRead();

  useEffect(() => { if (protectedView) setSignedIn(true); }, [protectedView]);
  const enter = async (details: { name: string; department: string }) => {
    const response = await fetch("/api/demo/session", { method: "POST", credentials: "same-origin", headers: { "content-type": "application/json" }, body: JSON.stringify(details) });
    if (!response.ok) throw new Error(response.status === 403 ? "Demo entry is unavailable." : "Unable to create a demo session. Please try again.");
    window.location.assign("/private");
  };
  const signOut = async () => { await fetch("/api/auth/refresh", { method: "DELETE", credentials: "same-origin" }); await authSignOut({ callbackUrl: "/login" }); };
  const navigate = (next: Page) => { setPage(next); setMenuOpen(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const openIdea = (id: number) => { setSelectedIdeaId(id); navigate("idea"); };
  if (!signedIn) return <AuthLoginScreen onEnter={enter} />;
  const points = rewardsSummaryQuery.data?.balance.balance ?? 0;
  const pageContent = page === "community" ? <EmployeeCommunityPage points={points} onNavigate={navigate} onOpenIdea={openIdea} /> : page === "new" ? <EmployeeIdeaSubmissionPage onOpenIdea={openIdea} /> : page === "learn" ? <LiveLearnPage /> : page === "library" ? <LiveLibraryPage onArticle={(id) => { setSelectedArticleId(id); navigate("article"); }} /> : page === "article" ? <LiveArticlePage articleId={selectedArticleId} onBack={() => navigate("library")} /> : page === "idea" && selectedIdeaId ? <EmployeeIdeaDetailPage ideaId={selectedIdeaId} onBack={() => navigate("community")} /> : page === "rewards" ? <LiveRewardsPage /> : page === "me" ? <AccountPage onNavigate={navigate} /> : page === "quiz" ? <LiveLearnPage /> : <EmployeeCommunityPage points={points} onNavigate={navigate} onOpenIdea={openIdea} />;
  return <div className="app-background min-h-screen"><div className="grid min-h-screen lg:grid-cols-[240px_1fr]"><SideNav page={page} open={menuOpen} onClose={() => setMenuOpen(false)} onNavigate={navigate} onSignOut={signOut} /><div className="min-w-0"><TopBar page={page} points={points} unreadCount={notificationsQuery.data?.unreadCount ?? 0} onMenu={() => setMenuOpen(true)} onNavigate={navigate} onNotifications={() => setNotificationsOpen(true)} /><main className="mx-auto w-full max-w-[1040px] px-3.5 pb-28 pt-[18px] sm:px-7 sm:pb-[70px] sm:pt-7">{pageContent}</main></div></div><MobileNav page={page} onNavigate={navigate} /><Notifications open={notificationsOpen} onClose={() => setNotificationsOpen(false)} items={notificationsQuery.data?.items ?? []} unreadCount={notificationsQuery.data?.unreadCount ?? 0} onMarkAllRead={() => setNotificationRead.mutate({ all: true, read: true })} /><div className="fixed inset-0 z-40 bg-navy/50 lg:hidden" onClick={() => setMenuOpen(false)} style={{ display: menuOpen ? "block" : "none" }} /></div>;
}
